import unreal_engine as ue
from unreal_engine.classes import DataTable

root = ue.get_project_root()
summary = {}

shop = ue.load_object(DataTable, root + '/Asset/Data/Table/UGCShop')
obj = ue.load_object(DataTable, root + '/Asset/Data/Table/UGCObject')

if shop:
    data = shop.data_table_as_dict()
    rows = []
    invalid = []
    exact_900001 = []
    exact_9000001 = []
    product_ids = []
    item1001_products = []
    for row_name, row in data.items():
        pid = getattr(row, 'ProductId', None)
        item = getattr(row, 'ItemID', None)
        pname = getattr(row, 'ProductName', None)
        info = {'row_name': str(row_name), 'ProductId': pid, 'ItemID': item, 'ProductName': pname}
        rows.append(info)
        if isinstance(pid, int):
            product_ids.append(pid)
            if pid < 9000000 or pid > 9999999:
                invalid.append(info)
        if pid == 900001:
            exact_900001.append(info)
        if pid == 9000001:
            exact_9000001.append(info)
        if item == 1001:
            item1001_products.append(info)
    summary['UGCShop'] = {
        'row_count': len(data),
        'min_product_id': min(product_ids) if product_ids else None,
        'max_product_id': max(product_ids) if product_ids else None,
        'invalid_product_id_rows': invalid,
        'has_product_900001': exact_900001,
        'has_product_9000001': exact_9000001,
        'products_with_ItemID_1001': item1001_products,
        'first_10_rows': rows[:10]
    }
else:
    summary['UGCShop'] = {'loaded': False}

if obj:
    data = obj.data_table_as_dict()
    item1001 = []
    invalid_items = []
    for row_name, row in data.items():
        iid = getattr(row, 'ItemID', None)
        info = {'row_name': str(row_name), 'ItemID': iid, 'ItemName': getattr(row, 'ItemName', None)}
        if iid == 1001:
            item1001.append(info)
        if isinstance(iid, int) and (iid < 1001 or iid > 10000):
            invalid_items.append(info)
    summary['UGCObject'] = {'row_count': len(data), 'item_1001': item1001, 'invalid_item_rows': invalid_items[:20]}
else:
    summary['UGCObject'] = {'loaded': False}

__askq_result = summary
